    /// Path to a real `aomenc` build carrying the reference options this
    /// fixture needs (`--max-partition-size`, `--enable-tx-size-search`,
    /// `--loopfilter-control`) -- this box's `ffmpeg` links a libaom too old
    /// to expose `enable-tx-size-search`/`loopfilter-control` through its
    /// own `-aom-params` passthrough (probed live: "Cannot find aom
    /// option"), so [`a_real_aomenc_filter_intra_stream_decodes_pixel_exact`]
    /// shells out to the standalone binary instead of ffmpeg's libaom-av1
    /// wrapper every other test here uses. `EC_AV1_AOMENC` overrides the
    /// default dev-build path; the test skips (not fails) when neither this
    /// nor `ffmpeg` is present.
    fn aomenc_path() -> std::path::PathBuf {
        if let Some(p) = std::env::var_os("EC_AV1_AOMENC") {
            return std::path::PathBuf::from(p);
        }
        // The oracle used to live only under `/tmp`, which this box's tmpfs
        // guard reclaims -- when it did, all 20 aomenc gates below went
        // silently vacuous (SKIP, suite still green). The durable location
        // is provisioned by `scripts/build-aom-oracle.sh`; the `/tmp` path
        // stays last as a legacy fallback.
        let mut candidates = Vec::new();
        if let Some(home) = std::env::var_os("HOME") {
            candidates.push(std::path::PathBuf::from(&home).join(".cache/aom-oracle/build/aomenc"));
        }
        candidates.push("/tmp/libaom-src/build/encoder/aomenc".into());
        candidates
            .iter()
            .find(|p| p.is_file())
            .cloned()
            .unwrap_or_else(|| candidates.remove(0))
    }

    /// Whether the aomenc oracle is present. Absence normally SKIPs (a
    /// checkout without the oracle should still run the rest of the suite),
    /// but `EC_AV1_REQUIRE_AOMENC=1` turns it into a hard failure so a batch
    /// run cannot report green off 20 skipped gates.
    /// Where a pinned stream lives. `fixtures/` is a symlink to a durable
    /// directory outside the repo, so a pin captured in one session is still
    /// there in the next; a session scratchpad is not (tmpfs reaps it, and
    /// four pins were silently dead because of that).
    fn pin_dir() -> std::path::PathBuf {
        if let Some(p) = std::env::var_os("EC_AV1_PIN_DIR") {
            return std::path::PathBuf::from(p);
        }
        std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures")
            .canonicalize()
            .unwrap_or_else(|_| std::path::PathBuf::from("fixtures"))
    }

    fn have_aomenc() -> bool {
        let present = aomenc_path().is_file();
        assert!(
            present || std::env::var_os("EC_AV1_REQUIRE_AOMENC").is_none(),
            "EC_AV1_REQUIRE_AOMENC is set but no aomenc at {} -- run scripts/build-aom-oracle.sh",
            aomenc_path().display()
        );
        present
    }

    /// The instrumented `aomdec` beside the `aomenc` oracle
    /// (`scripts/build-aom-oracle.sh` + `scripts/instrument-aom-oracle.sh`).
    fn aomdec_path() -> std::path::PathBuf {
        if let Some(p) = std::env::var_os("EC_AV1_AOMDEC") {
            return std::path::PathBuf::from(p);
        }
        aomenc_path().with_file_name("aomdec")
    }

    /// Decodes `stream` with both this decoder and the instrumented oracle
    /// `aomdec`, and compares EVERY decoded frame in DECODE order --
    /// including the hidden (`show_frame == 0`) alt-ref frames no other gate
    /// in this repo can see, because `decode_stream` only pushes shown
    /// frames and `ffmpeg -f obu ... rawvideo` only emits shown frames
    /// (class gate-blind-to-hidden-frames: a hidden frame's defect surfaces
    /// only as drift on some later shown frame, if at all).
    ///
    /// Both sides write the final, post-deblock/CDEF/LR/superres frame as it
    /// is stored into the reference buffer (`EC_AV1_FINAL_DUMP`, ours in
    /// `decode_stream`, the oracle's in rung 12 of
    /// `scripts/instrument-aom-oracle.sh`), 8-bit as u8 / high bitdepth as
    /// u16 LE. Returns `(frames_decoded, hidden_frames)`.
    fn decode_all_frames_vs_oracle(stream: &[u8], name: &str) -> (usize, usize) {
        let dir = std::env::temp_dir().join(format!("ec-av1-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("scratch dir");
        let obu = dir.join("in.obu");
        std::fs::write(&obu, stream).expect("writing the stream");
        let aom_prefix = dir.join("aom");
        let out = Command::new(aomdec_path())
            .args(["--codec=av1", "-o"])
            .arg(dir.join("out.y4m"))
            .arg(&obu)
            .env("EC_AV1_FINAL_DUMP", &aom_prefix)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .output()
            .expect("aomdec failed to run");
        assert!(
            out.status.success(),
            "{name}: the oracle aomdec refused the stream: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let count_dumps = |prefix: &std::path::Path| -> usize {
            let mut n = 0usize;
            while std::path::PathBuf::from(format!("{}.f{n}", prefix.display())).is_file() {
                n += 1;
            }
            n
        };
        let oracle_frames = count_dumps(&aom_prefix);
        assert!(
            oracle_frames > 0,
            "{name}: the oracle wrote no EC_AV1_FINAL_DUMP frames -- rung 12 of \
             scripts/instrument-aom-oracle.sh is missing from {}",
            aomdec_path().display()
        );
        let ours_prefix = dir.join("ours");
        set_final_dump_prefix(Some(ours_prefix.display().to_string()));
        let decoded = decode_stream(stream);
        set_final_dump_prefix(None);
        let shown = decoded
            .unwrap_or_else(|e| panic!("{name}: this decoder refused the stream: {e}"))
            .len();
        let our_frames = count_dumps(&ours_prefix);
        assert_eq!(
            our_frames, oracle_frames,
            "{name}: decoded {our_frames} frames in decode order, the oracle decoded \
             {oracle_frames}"
        );
        for i in 0..oracle_frames {
            let want =
                std::fs::read(format!("{}.f{i}", aom_prefix.display())).expect("oracle dump");
            let got = std::fs::read(format!("{}.f{i}", ours_prefix.display())).expect("our dump");
            assert_eq!(
                got.len(),
                want.len(),
                "{name}: decode-order frame {i} is {} bytes, the oracle's is {}",
                got.len(),
                want.len()
            );
            if let Some(at) = got.iter().zip(&want).position(|(a, b)| a != b) {
                let differing = got.iter().zip(&want).filter(|(a, b)| a != b).count();
                panic!(
                    "{name}: decode-order frame {i} of {oracle_frames} ({shown} shown, {} \
                     hidden) differs from the oracle at byte {at} (ours {} vs {}), {differing} \
                     bytes differ -- stream pinned at {}",
                    oracle_frames - shown,
                    got[at],
                    want[at],
                    obu.display()
                );
            }
        }
        let hidden = oracle_frames - shown;
        let _ = std::fs::remove_dir_all(&dir);
        (oracle_frames, hidden)
    }

    /// lane-hidden r2: the `--arnr-maxframes=0` SECOND ARM of an existing
    /// gate -- the gate's own recipe is never changed, this re-encodes the
    /// same fixture with libaom's temporal alt-ref filter switched off and
    /// runs [`decode_all_frames_vs_oracle`] on the result. Measured: with
    /// the filter at its default EVERY alt-ref recipe in this file emits
    /// ZERO hidden frames (the candidates are filtered away), so the
    /// hidden-frame compare on the gate's own stream is vacuous; this arm
    /// is what actually puts `show_frame == 0` frames on the wire.
    ///
    /// Runs at most once per gate name per process (the loop gates sweep
    /// dozens of attempts and each arm costs a full encode + two decodes).
    /// A stream this decoder refuses BY NAME skips the arm -- the arm is
    /// about hidden frames, not about that capability gap -- while a pixel
    /// mismatch is a hard failure raised inside the compare.
    fn hidden_arnr_arm(name: &str, y4m: &[u8], args: &[&str]) -> Option<(usize, usize)> {
        static ARMED: std::sync::OnceLock<std::sync::Mutex<std::collections::HashSet<String>>> =
            std::sync::OnceLock::new();
        if !ARMED
            .get_or_init(Default::default)
            .lock()
            .unwrap()
            .insert(name.to_string())
        {
            return None;
        }
        let mut arm: Vec<&str> = vec!["--arnr-maxframes=0"];
        arm.extend_from_slice(args);
        let mut child = Command::new(aomenc_path())
            .args(&arm)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("aomenc failed to start");
        child
            .stdin
            .take()
            .expect("aomenc stdin")
            .write_all(y4m)
            .expect("writing y4m to aomenc");
        let out = child.wait_with_output().expect("aomenc failed to run");
        assert!(
            out.status.success(),
            "{name} HIDDEN-ARM: aomenc refused its own recipe plus --arnr-maxframes=0: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let stream = out.stdout;
        match decode_stream(&stream) {
            Err(e) => {
                let msg = e.to_string();
                assert!(
                    msg.contains("unsupported"),
                    "{name} HIDDEN-ARM failed outright: {msg}"
                );
                eprintln!("{name} HIDDEN-ARM: skipped on a named refusal: {msg}");
                None
            }
            Ok(_) => Some(decode_all_frames_vs_oracle(&stream, &format!("{name}-arnr0"))),
        }
    }


    /// The repo's first hidden-frame pixel gate. Every other aomenc gate
    /// here compares `decode_stream`'s output against `ffmpeg -f obu`, and
    /// both sides emit SHOWN frames only -- so an alt-ref frame that is
    /// decoded, stored into a reference slot and never displayed was, until
    /// this gate, never compared to anything (class
    /// gate-blind-to-hidden-frames). His films are aomenc-encoded with the
    /// default `--lag-in-frames`, so they are full of exactly these frames.
    ///
    /// `--auto-alt-ref=1 --lag-in-frames=25` on moving content makes aomenc
    /// build alt-refs; `--arnr-maxframes=0` is load-bearing -- with libaom's
    /// temporal filter on, this fixture's alt-ref candidates get filtered
    /// away and the encoder emits ZERO hidden frames (measured: 0 hidden
    /// with the filter on, 3 with it off), which would have made the gate
    /// vacuous. The `hidden >= 2` assertion is hard, on both bit depths, so
    /// a recipe that stops producing hidden frames fails rather than skips.
    #[test]
    fn a_real_aomenc_altref_sequence_hidden_frames_decode_pixel_exact() {
        const NAME: &str = "a_real_aomenc_altref_sequence_hidden_frames_decode_pixel_exact";
        let _gate_lock = lock_gate_counters();
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        for bit_depth in [8u32, 10u32] {
            let (width, height, frames) = (64usize, 64usize, 40usize);
            let duration = frames as f64 / 25.0;
            let source = format!("testsrc2=size={width}x{height}:duration={duration}:rate=25");
            let pix_fmt = if bit_depth == 10 { "yuv420p10le" } else { "yuv420p" };
            let y4m = Command::new("ffmpeg")
                .args([
                    "-v", "error", "-f", "lavfi", "-i", &source, "-t", &duration.to_string(),
                    "-pix_fmt", pix_fmt, "-strict", "-1", "-f", "yuv4mpegpipe", "-",
                ])
                .stdin(Stdio::null())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .output()
                .expect("ffmpeg failed to run");
            assert!(
                y4m.status.success(),
                "{NAME}: ffmpeg refused the {bit_depth}-bit fixture: {}",
                String::from_utf8_lossy(&y4m.stderr)
            );
            let depth_arg = format!("--bit-depth={bit_depth}");
            let input_depth_arg = format!("--input-bit-depth={bit_depth}");
            let mut child = Command::new(aomenc_path())
                .args([
                    // lane-defon r1: the repo's only gate that decodes hidden
                    // frames is also the only place a FORWARD KEYFRAME can be
                    // proven -- a KEY frame with `show_frame == 0`, which is
                    // exactly the shape this gate already compares in decode
                    // order. On-values go before the base list (aomenc keeps
                    // the FIRST occurrence of a repeated flag).
                    "--enable-fwd-kf=1",
                    "--fwd-kf-dist=8",
                    "--codec=av1",
                    "--passes=1",
                    "--end-usage=q",
                    "--cq-level=45",
                    "--cpu-used=0",
                    "--threads=1",
                    "--row-mt=0",
                    "--kf-max-dist=1000",
                    "--enable-order-hint=1",
                    "--auto-alt-ref=1",
                    "--lag-in-frames=25",
                    "--arnr-maxframes=0",
                    &depth_arg,
                    &input_depth_arg,
                    // The same tool set every sibling inter gate pins -- the
                    // open capability gaps (rect/AB partitions, warped/OBMC,
                    // masked compound, palette, ...) are other lanes' work;
                    // this gate is about hidden frames, not about them.
                    "--enable-warped-motion=0",
                    // OBMC stays off HERE (this gate is about hidden frames);
                    // the tool's own coverage is the `obmc*` gates and, on a
                    // 16x8/8x16 leaf, the `--enable-obmc=1` arm of
                    // `..._with_a_16_level_rect_leaf_...` (lane-inter4 r4).
                    "--enable-obmc=0",
                    "--enable-masked-comp=0",
                    "--enable-interintra-comp=0",
                    "--enable-onesided-comp=0",
                    "--enable-interintra-wedge=0",
                    "--enable-smooth-interintra=0",
                    "--enable-rect-partitions=0",
                    "--enable-ab-partitions=0",
                    "--enable-1to4-partitions=0",
                    "--enable-filter-intra=0",
                    "--enable-smooth-intra=0",
                    "--enable-paeth-intra=0",
                    "--enable-directional-intra=0",
                    "--enable-angle-delta=0",
                    "--enable-tx-size-search=0",
                    "--enable-cdef=0",
                    "--enable-restoration=0",
                    "--max-partition-size=32",
                    "--min-partition-size=32",
                    "--enable-palette=0",
                    "--enable-intrabc=0",
                    "--enable-cfl-intra=0",
                    "--enable-ref-frame-mvs=0",
                    "--obu",
                    "-o",
                    "-",
                    "-",
                ])
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .expect("aomenc failed to start");
            child
                .stdin
                .take()
                .expect("aomenc stdin")
                .write_all(&y4m.stdout)
                .expect("writing y4m to aomenc");
            let out = child.wait_with_output().expect("aomenc failed to run");
            assert!(
                out.status.success(),
                "{NAME}: aomenc refused the {bit_depth}-bit fixture: {}",
                String::from_utf8_lossy(&out.stderr)
            );
            let stream = out.stdout;
            let fwd_kf_before = crate::decode::fwd_kf_hits();
            let (total, hidden) =
                decode_all_frames_vs_oracle(&stream, &format!("altref-hidden-{bit_depth}bit"));
            let fwd_kf = crate::decode::fwd_kf_hits() - fwd_kf_before;
            assert!(
                hidden >= 2,
                "{NAME}: the {bit_depth}-bit recipe produced only {hidden} hidden frame(s) of \
                 {total} decoded -- the gate would be vacuous (class \
                 gate-blind-to-hidden-frames)"
            );
            // lane-defon r1: `--enable-fwd-kf=1` is spelled on this recipe, so
            // a KEY frame with `show_frame == 0` must actually have been
            // decoded -- otherwise the on-value proves nothing.
            assert!(
                fwd_kf > 0,
                "{NAME}: the {bit_depth}-bit recipe decoded {total} frames ({hidden} hidden) but \
                 zero forward keyframes -- --enable-fwd-kf=1 --fwd-kf-dist=8 never reached the \
                 bitstream"
            );
            eprintln!(
                "{NAME} {bit_depth}-bit: {total} frames decoded, {hidden} hidden, {fwd_kf} \
                 forward keyframes, all pixel-exact vs the oracle in decode order"
            );
        }
    }

    /// A real `aomenc` filter-intra fixture: every other intra mode disabled
    /// (smooth/paeth/directional/angle-delta) and
    /// `--max-partition-size=32` (past which `av1_filter_intra_allowed_bsize`'s
    /// <=32x32 bound means `use_filter_intra` never reads at all, spec
    /// 5.11.14), so the only way this frame codes is `DC_PRED` with filter
    /// intra on top -- `--loopfilter-control=0` is required too: this
    /// decoder has no in-loop deblocking filter at all, and libaom's default
    /// (on) smooths every block-boundary column, which first looked like a
    /// filter-intra math bug (mismatches straddling the 32-pixel block
    /// seam) until the recipe without it round-tripped byte-exact. Checks
    /// [`decode::filter_intra_hits`] actually moved (a process-global
    /// counter, so before/after rather than an absolute value) to prove the
    /// symbol fired, then pixel-exactness against ffmpeg's own decode of the
    /// identical bytes on every plane.
    #[test]
    fn a_real_aomenc_filter_intra_stream_decodes_pixel_exact() {
        if !have_ffmpeg() {
            eprintln!("SKIP a_real_aomenc_filter_intra_stream_decodes_pixel_exact: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!(
                "SKIP a_real_aomenc_filter_intra_stream_decodes_pixel_exact: no aomenc at {}",
                aomenc_path().display()
            );
            return;
        }
        let (width, height) = (64usize, 64usize);
        // Recipe-search hooks: with the encoder pinned to one thread the
        // stream is a deterministic function of (seed, cq), so a firing recipe
        // can be searched for without a rebuild.
        let fi_seed: u32 = std::env::var("EC_FI_SEED")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(42);
        let fi_source = gradients_source(fi_seed, 64, 64, "duration=0.04:rate=25");
        let fi_cq = std::env::var("EC_FI_CQ").unwrap_or_else(|_| "40".to_string());
        let fi_cq_arg = format!("--cq-level={fi_cq}");
        let y4m = Command::new("ffmpeg")
            .args([
                "-v",
                "error",
                "-f",
                "lavfi",
                "-i",
                &fi_source,
                "-pix_fmt",
                "yuv420p",
                "-f",
                "yuv4mpegpipe",
                "-",
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .output()
            .expect("ffmpeg failed to run");
        assert!(
            y4m.status.success(),
            "ffmpeg refused to generate the y4m fixture: {}",
            String::from_utf8_lossy(&y4m.stderr)
        );
        let mut child = Command::new(aomenc_path())
            .args([
                "--codec=av1",
                "--passes=1",
                "--end-usage=q",
                &fi_cq_arg,
                "--cpu-used=0",
                // Every sibling gate pins these; this one did not, and a
                // multi-threaded aomenc is not deterministic, so each run
                // encoded a slightly different stream and the gate flaked
                // against whichever features that run happened to pick.
                // Pinning them makes seed 42 mean one stream (class
                // `parallel-flake-is-attempt-selection`).
                "--threads=1",
                "--row-mt=0",
                "--enable-filter-intra=1",
                "--enable-smooth-intra=0",
                "--enable-paeth-intra=0",
                "--enable-directional-intra=0",
                "--enable-angle-delta=0",
                "--enable-tx-size-search=0",
                "--enable-cdef=0",
                "--max-partition-size=32",
                "--loopfilter-control=0",
                "--enable-palette=0",
                "--enable-intrabc=0",
                "--obu",
                "-o",
                "-",
                "-",
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("aomenc failed to start");
        child
            .stdin
            .take()
            .expect("aomenc stdin")
            .write_all(&y4m.stdout)
            .expect("writing the y4m fixture to aomenc");
        let out = child.wait_with_output().expect("aomenc failed to run");
        assert!(
            out.status.success(),
            "aomenc refused the fixture: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let stream = out.stdout;
        let before = decode::filter_intra_hits();
        // `screen_content_tools_determination` (libaom encoder_utils.c) is a
        // real internal trial-encode/PSNR comparison, not a flag this CLI
        // exposes a knob for -- on this flat gradient fixture it lands on
        // `allow_screen_content_tools=0` most runs but occasionally trips
        // over its 0.9 dB threshold the other way even with palette/intrabc
        // both disabled. That is a genuine separate gap (`decode_stream`
        // never reads `intrabc`/`palette_mode_info`), not a filter-intra
        // regression, so it is skipped here exactly as
        // `a_real_libaom_gradients_stream_with_cdef_decodes_pixel_exact`
        // above skips its own still-unsupported-gap runs.
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => {
                eprintln!("SKIP a_real_aomenc_filter_intra_stream_decodes_pixel_exact: {e}");
                return;
            }
        };
        assert!(
            decode::filter_intra_hits() > before,
            "use_filter_intra never fired decoding this stream"
        );
        let ffmpeg_frames = ffmpeg_decode_sequence(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "luma vs ffmpeg");
        assert_eq!(frames[0].u, ffmpeg_frames[0].u, "U vs ffmpeg");
        assert_eq!(frames[0].v, ffmpeg_frames[0].v, "V vs ffmpeg");
    }

    /// A real `aomenc` palette-Y fixture (lane-palette r3): `smptebars`
    /// (SMPTE colour bars -- a handful of large flat luma regions, exactly
    /// the "flat, few-colour, repetitive" content `av1_choose_palette_map`'s
    /// RD trial rewards) with `hue=s=0` to flatten chroma to one constant
    /// value, so `DC_PRED` already nails every chroma block with zero
    /// residual and the encoder's own RD never has a reason to spend bits on
    /// a *UV* palette too (a real symbol this decoder still refuses --
    /// lane-palette r3's own scope is Y only). `smptebars` has no seed to
    /// vary, so the fixture is deterministic by construction; hashed twice
    /// below to prove it rather than assert it. `--enable-rect-partitions=0`
    /// / `-ab-` / `-1to4-` keep every intra block square, sidestepping the
    /// rect-strip screen-content refusal at `read_intra_mode_rect`
    /// (decode.rs ~2226) -- that refusal is this lane's own next milestone,
    /// not this gate's. `--sb-size=64` and `--threads=1 --row-mt=0` are the
    /// sibling-lane facts this charter paid for: a single 64x64 frame is one
    /// superblock either way, but pinning them keeps the recipe identical to
    /// every other gate in this file. HARD-asserts
    /// [`decode::palette_hits`] moved -- a stream that never reads a real
    /// palette block would refuse (or not) by construction without proving
    /// this milestone at all.
    ///
    /// lane-palette r4/r6/r7: r3/r4 found that this fixture's reconstructed
    /// pixels did not match ffmpeg's decode of the same bytes even though
    /// every symbol read by `decode_color_index_map` checked line-for-line
    /// against the oracle and matched. r6's range trace (`compare-range-not-tell`)
    /// pinned the real cause: `decode_color_index_map` was called from the
    /// wrong syntax position -- inline right after the Y colours, instead of
    /// after the whole mode-info read (UV palette mode_info + `filter_intra`,
    /// `av1_visit_palette`'s real call order). r7 ported the UV palette
    /// mode_info read and moved the colour-index-map decode after
    /// `filter_intra`; this gate now asserts a real pixel match instead of
    /// the old named refusal.
    #[test]
    fn a_real_aomenc_stream_with_palette_y_decodes_pixel_exact() {
        const NAME: &str = "a_real_aomenc_stream_with_palette_y_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let source = "smptebars=size=64x64:rate=25";
        fn render(source: &str) -> Vec<u8> {
            Command::new("ffmpeg")
                .args([
                    "-v",
                    "error",
                    "-f",
                    "lavfi",
                    "-i",
                    source,
                    "-vf",
                    "hue=s=0",
                    "-pix_fmt",
                    "yuv420p",
                    "-t",
                    "0.04",
                    "-f",
                    "yuv4mpegpipe",
                    "-",
                ])
                .stdin(Stdio::null())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .output()
                .expect("ffmpeg failed to run")
                .stdout
        }
        let y4m_a = render(source);
        let y4m_b = render(source);
        assert_eq!(
            y4m_a, y4m_b,
            "smptebars must render byte-identical across two runs"
        );
        let y4m = y4m_a;
        let mut child = Command::new(aomenc_path())
            .args([
                "--codec=av1",
                "--passes=1",
                "--end-usage=q",
                "--cq-level=30",
                "--cpu-used=0",
                "--threads=1",
                "--row-mt=0",
                "--sb-size=64",
                "--tune-content=screen",
                "--enable-palette=1",
                "--enable-intrabc=0",
                "--enable-rect-partitions=0",
                "--enable-ab-partitions=0",
                "--enable-1to4-partitions=0",
                "--min-partition-size=32",
                "--max-partition-size=32",
                "--enable-filter-intra=0",
                "--enable-smooth-intra=0",
                "--enable-paeth-intra=0",
                "--enable-directional-intra=0",
                "--enable-angle-delta=0",
                "--enable-cfl-intra=0",
                "--enable-cdef=0",
                "--enable-restoration=0",
                "--enable-tx-size-search=0",
                "--loopfilter-control=0",
                "--obu",
                "-o",
                "-",
                "-",
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("aomenc failed to start");
        child
            .stdin
            .take()
            .expect("aomenc stdin")
            .write_all(&y4m)
            .expect("writing y4m to aomenc");
        let out = child.wait_with_output().expect("aomenc failed to run");
        assert!(
            out.status.success(),
            "aomenc refused the fixture: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let stream = out.stdout;
        let before = decode::palette_hits();
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused: {e}"),
        };
        assert!(
            decode::palette_hits() > before,
            "palette_y_mode never fired decoding this stream -- gate is vacuous"
        );
        let ffmpeg_frames = ffmpeg_decode_sequence(&stream, 64, 64, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "luma vs ffmpeg");
        assert_eq!(frames[0].u, ffmpeg_frames[0].u, "U vs ffmpeg");
        assert_eq!(frames[0].v, ffmpeg_frames[0].v, "V vs ffmpeg");
    }

    /// lane-kf900 r3: the palette colour reader at BOTH bit depths.
    ///
    /// `read_palette_colors_y`/`_uv` (decode.rs, mirroring `decodemv.c:478`
    /// and `:509`) size every raw literal they read by the sequence's
    /// `bit_depth`: the first colour is `bit_depth` bits, `min_bits` is
    /// `bit_depth - 3` (Y/U) or `bit_depth - 4` (V), `range` starts at
    /// `1 << bit_depth`, and the clamp/wrap bound is `(1 << bit_depth) - 1`.
    /// Ours hardcoded 8, so every 10-bit palette block read TWO BITS TOO FEW
    /// per transmitted colour and silently decoded the rest of the tile from
    /// the wrong bit position.
    ///
    /// It was silent because raw literals are EQUIPROBABLE: at the ranges
    /// this content reaches an equiprobable read maps the msac range onto
    /// itself (62728 -> 31364 -> renormalised 62728), so a cross-decoder
    /// RANGE ladder stays bit-identical straight through the miscount and
    /// only the decoded VALUE moves. Pinned on a 256x192 10-bit
    /// `--cq-level=59` stream whose first block is a 32x16 palette: aomdec's
    /// `EC_PAL` ladder and ours agreed on every range and disagreed on the
    /// very first colour index (0 vs 1); after the fix all 1024 `EC_PAL`
    /// lines of that block match aomdec line for line.
    ///
    /// The recipe is the 8-bit `..._with_palette_y_...` gate's, with the
    /// depth as the only variable, so a failure here is the depth and
    /// nothing else. HARD-asserts [`decode::palette_hits`] moved on each arm
    /// (a stream with no real palette block would prove nothing) and
    /// compares all three planes against ffmpeg's decode of the same bytes.
    #[test]
    fn a_real_aomenc_palette_stream_decodes_pixel_exact_at_8_and_10_bit() {
        const NAME: &str = "a_real_aomenc_palette_stream_decodes_pixel_exact_at_8_and_10_bit";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let (width, height) = (64usize, 64usize);
        for depth in [8usize, 10] {
            let pix_fmt = if depth == 10 { "yuv420p10le" } else { "yuv420p" };
            let render = || {
                Command::new("ffmpeg")
                    .args([
                        "-v", "error",
                        "-f", "lavfi",
                        "-i", "smptebars=size=64x64:rate=25",
                        "-vf", "hue=s=0",
                        "-pix_fmt", pix_fmt,
                        "-strict", "-1",
                        "-t", "0.04",
                        "-f", "yuv4mpegpipe",
                        "-",
                    ])
                    .stdin(Stdio::null())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .output()
                    .expect("ffmpeg failed to run")
                    .stdout
            };
            let y4m_a = render();
            let y4m_b = render();
            assert_eq!(
                y4m_a, y4m_b,
                "{NAME}: smptebars must render byte-identical across two runs at {depth}-bit"
            );
            let y4m = y4m_a;
            let depth_arg = format!("--bit-depth={depth}");
            let input_depth_arg = format!("--input-bit-depth={depth}");
            let mut child = Command::new(aomenc_path())
                .args([
                    "--codec=av1",
                    "--passes=1",
                    "--end-usage=q",
                    "--cq-level=30",
                    "--cpu-used=0",
                    "--threads=1",
                    "--row-mt=0",
                    "--sb-size=64",
                    "--tune-content=screen",
                    "--enable-palette=1",
                    "--enable-intrabc=0",
                    "--enable-rect-partitions=0",
                    "--enable-ab-partitions=0",
                    "--enable-1to4-partitions=0",
                    "--min-partition-size=32",
                    "--max-partition-size=32",
                    "--enable-filter-intra=0",
                    "--enable-smooth-intra=0",
                    "--enable-paeth-intra=0",
                    "--enable-directional-intra=0",
                    "--enable-angle-delta=0",
                    "--enable-cfl-intra=0",
                    "--enable-cdef=0",
                    "--enable-restoration=0",
                    "--enable-tx-size-search=0",
                    "--loopfilter-control=0",
                    "--limit=1",
                ])
                // Per-arm overrides go AFTER the base recipe: aomenc keeps the
                // LAST occurrence of a repeated flag.
                .args([&depth_arg, &input_depth_arg])
                .args(["--obu", "-o", "-", "-"])
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .expect("aomenc failed to start");
            child
                .stdin
                .take()
                .expect("aomenc stdin")
                .write_all(&y4m)
                .expect("writing y4m to aomenc");
            let out = child.wait_with_output().expect("aomenc failed to run");
            assert!(
                out.status.success(),
                "{NAME}: aomenc refused the {depth}-bit fixture: {}",
                String::from_utf8_lossy(&out.stderr)
            );
            let stream = out.stdout;
            let before = decode::palette_hits();
            let frames = match decode_stream(&stream) {
                Ok(frames) => frames,
                Err(e) => panic!("{NAME}: decode_stream refused the {depth}-bit stream: {e}"),
            };
            assert!(
                decode::palette_hits() > before,
                "{NAME}: no real palette block at {depth}-bit -- gate is vacuous"
            );
            let ffmpeg_frames = if depth == 10 {
                ffmpeg_decode_sequence_10bit(&stream, width, height, 1)
            } else {
                ffmpeg_decode_sequence(&stream, width, height, 1)
            };
            assert_eq!(frames[0].y, ffmpeg_frames[0].y, "{NAME}: luma at {depth}-bit");
            assert_eq!(frames[0].u, ffmpeg_frames[0].u, "{NAME}: U at {depth}-bit");
            assert_eq!(frames[0].v, ffmpeg_frames[0].v, "{NAME}: V at {depth}-bit");
        }
    }

    /// lane-pal8 r1, the gate for a palette on a SQUARE 8x8 LEAF.
    ///
    /// `read_palette_mode_info` (decodemv.c:567) reads `palette_y_mode` for
    /// every `DC_PRED` block whose `av1_get_palette_bsize_ctx`
    /// (`num_pels_log2 - num_pels_log2[BLOCK_8X8]`, 0 at 8x8) exists, and
    /// `av1_decode_palette_tokens` (decodeframe.c:1135, `av1_visit_palette`)
    /// reads the colour-index map after the WHOLE mode-info read. Ours passed
    /// `None`/`&[]` from [`decode::decode_leaf8`], reading the mode symbol off
    /// CDF row 0 and refusing "a block that actually uses a palette (Y) --
    /// reconstruction is out of scope" the moment it fired -- and at 8 bit
    /// aomenc palettes SQUARE blocks, so with `--min-partition-size=8` every
    /// 8-bit screen-content stream stopped there (lane-kf900 r4's measurement).
    ///
    /// Sweeps both bit depths x cq 30/40/55 x `--enable-tx-size-search` 0/1 x
    /// two lavfi sources (+ a `--tile-columns=1` arm, per the neighbour-map
    /// rule: the palette bands are per-mi and tile-guarded). Key frame only
    /// (`--limit=1`): the inter frames of these recipes stop on OTHER lanes'
    /// open refusals (8x8 inter leaf chroma mode, inter 1:4 partitions).
    /// HARD-asserts the 8x8-leaf palette counter moved on the compared arms
    /// and that no arm mismatched, in or out of scope.
    #[test]
    fn a_real_aomenc_palette_stream_with_8x8_leaves_decodes_pixel_exact() {
        const NAME: &str = "a_real_aomenc_palette_stream_with_8x8_leaves_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let (width, height) = (128usize, 128usize);
        let (mut leaf8_total, mut fired_arms, mut compared, mut frames_compared) =
            (0usize, 0u32, 0u32, 0usize);
        let (mut out_of_scope, mut out_of_scope_mismatch, mut refusals) = (0u32, 0u32, 0u32);
        let (mut sb_strip_total, mut sb_strip_arms) = (0usize, 0u32);
        // The one palette shape this round did NOT lift (measured: lifting it
        // mismatches -- see [`decode_block_rect64`]'s own comment).
        let mut sb_strip_refusals = 0u32;
        for src in ["testsrc2", "smptebars"] {
            for depth in [8usize, 10usize] {
                for cq in [30usize, 40, 55] {
                    for txs in [0usize, 1] {
                        for tiles in [0usize, 1] {
                            let arm = format!("{src}-{depth}bit-cq{cq}-txs{txs}-tc{tiles}");
                            let pix_fmt = if depth == 10 { "yuv420p10le" } else { "yuv420p" };
                            let size = format!("{src}=size={width}x{height}:rate=25");
                            let render = || {
                                let out = Command::new("ffmpeg")
                                    .args([
                                        "-v", "error", "-f", "lavfi", "-i", &size, "-t", "0.04",
                                        "-pix_fmt", pix_fmt, "-strict", "-1", "-f",
                                        "yuv4mpegpipe", "-",
                                    ])
                                    .stdin(Stdio::null())
                                    .stdout(Stdio::piped())
                                    .stderr(Stdio::piped())
                                    .output()
                                    .expect("ffmpeg failed to run");
                                assert!(out.status.success(), "{NAME}: ffmpeg failed for {arm}");
                                out.stdout
                            };
                            let y4m_a = render();
                            let y4m_b = render();
                            assert_eq!(
                                y4m_a, y4m_b,
                                "{NAME}: {arm} must render byte-identical across two runs"
                            );
                            let y4m = y4m_a;
                            let depth_arg = format!("--bit-depth={depth}");
                            let input_depth_arg = format!("--input-bit-depth={depth}");
                            let cq_arg = format!("--cq-level={cq}");
                            let txs_arg = format!("--enable-tx-size-search={txs}");
                            let tiles_arg = format!("--tile-columns={tiles}");
                            let mut child = Command::new(aomenc_path())
                                .args([
                                    "--codec=av1",
                                    "--passes=1",
                                    "--end-usage=q",
                                    "--cpu-used=0",
                                    "--threads=1",
                                    "--row-mt=0",
                                    "--lag-in-frames=0",
                                    "--limit=1",
                                    "--sb-size=64",
                                    "--tune-content=screen",
                                    "--enable-palette=1",
                                    "--enable-intrabc=0",
                                    "--min-partition-size=8",
                                    "--enable-cdef=0",
                                    "--enable-restoration=0",
                                    "--loopfilter-control=0",
                                ])
                                // aomenc keeps the LAST occurrence of a repeated flag,
                                // so per-arm overrides go after the base recipe.
                                .args([&depth_arg, &input_depth_arg, &cq_arg, &txs_arg, &tiles_arg])
                                .args(["--obu", "-o", "-", "-"])
                                .stdin(Stdio::piped())
                                .stdout(Stdio::piped())
                                .stderr(Stdio::piped())
                                .spawn()
                                .expect("aomenc failed to start");
                            child
                                .stdin
                                .take()
                                .expect("aomenc stdin")
                                .write_all(&y4m)
                                .or_else(|e| match e.kind() {
                                    std::io::ErrorKind::BrokenPipe => Ok(()),
                                    _ => Err(e),
                                })
                                .expect("writing y4m to aomenc");
                            let out = child.wait_with_output().expect("aomenc failed to run");
                            assert!(
                                out.status.success(),
                                "{NAME}: aomenc refused {arm}: {}",
                                String::from_utf8_lossy(&out.stderr)
                            );
                            let stream = out.stdout;
                            decode::reset_palette_leaf8_hits();
                            decode::reset_palette_sb_strip_hits();
                            let decoded = decode_stream(&stream);
                            let leaf8 = decode::palette_leaf8_hits();
                            let sb_strip = decode::palette_sb_strip_hits();
                            leaf8_total += leaf8;
                            sb_strip_total += sb_strip;
                            match decoded {
                                Ok(frames) => {
                                    assert!(!frames.is_empty(), "{NAME}: {arm} decoded no frame");
                                    let theirs = if depth == 10 {
                                        ffmpeg_decode_sequence_10bit(
                                            &stream,
                                            width,
                                            height,
                                            frames.len(),
                                        )
                                    } else {
                                        ffmpeg_decode_sequence(&stream, width, height, frames.len())
                                    };
                                    assert_eq!(
                                        frames.len(),
                                        theirs.len(),
                                        "{NAME}: {arm} frame count"
                                    );
                                    let mut same = true;
                                    for (i, (ours, ref_f)) in
                                        frames.iter().zip(theirs.iter()).enumerate()
                                    {
                                        let ok = ours.y == ref_f.y
                                            && ours.u == ref_f.u
                                            && ours.v == ref_f.v;
                                        if !ok {
                                            eprintln!("{NAME}: {arm} MISMATCH at frame {i}");
                                        }
                                        same &= ok;
                                        frames_compared += 1;
                                    }
                                    compared += 1;
                                    if sb_strip > 0 {
                                        sb_strip_arms += 1;
                                        assert!(
                                            same,
                                            "{NAME}: {arm} decoded {sb_strip} non-skip palette \
                                             block(s) on a superblock-level strip and did not \
                                             match ffmpeg"
                                        );
                                    }
                                    if leaf8 > 0 || sb_strip > 0 {
                                        fired_arms += 1;
                                        assert!(
                                            same,
                                            "{NAME}: {arm} decoded {leaf8} 8x8-leaf palette \
                                             block(s) and did not match ffmpeg"
                                        );
                                    } else {
                                        out_of_scope += 1;
                                        if !same {
                                            out_of_scope_mismatch += 1;
                                        }
                                    }
                                    eprintln!(
                                        "{NAME}: {arm} {} frame(s), {leaf8} 8x8-leaf palette \
                                         block(s), {sb_strip} superblock-strip palette \
                                         block(s), exact={same}",
                                        frames.len()
                                    );
                                }
                                Err(e) => {
                                    let msg = e.to_string();
                                    assert!(
                                        msg.contains("unsupported"),
                                        "{NAME}: {arm} decode failed: {e}"
                                    );
                                    // Named, counted, never turned into a skip.
                                    if msg.contains("superblock-level HORZ/VERT strip") {
                                        sb_strip_refusals += 1;
                                    }
                                    eprintln!("{NAME}: {arm} REFUSED: {e}");
                                    refusals += 1;
                                }
                            }
                        }
                    }
                }
            }
        }
        eprintln!(
            "{NAME}: {leaf8_total} 8x8-leaf palette block(s) across {fired_arms} arm(s), \
             {compared} arms compared ({frames_compared} frames), {sb_strip_total} \
             superblock-strip palette block(s) across {sb_strip_arms} arm(s), \
             {out_of_scope} out of scope ({out_of_scope_mismatch} mismatched), \
             {refusals} refused ({sb_strip_refusals} superblock-strip palette)"
        );
        assert!(
            leaf8_total > 0 && fired_arms > 0,
            "{NAME}: gate is vacuous -- no compared arm decoded an 8x8-leaf palette block"
        );
        assert!(
            sb_strip_refusals > 0,
            "{NAME}: no arm reached the superblock-strip palette refusal -- the open residue \
             this gate documents is no longer exercised"
        );
        assert_eq!(
            out_of_scope_mismatch, 0,
            "{NAME}: an out-of-scope arm mismatched ffmpeg -- a defect, never a skip"
        );
        assert!(frames_compared > 0, "{NAME}: no frame was compared pixel-exact");
    }

    /// lane-kf900 r5, the gate for the rect-strip `use_intrabc` read.
    ///
    /// `av1_allow_intrabc` is a FRAME-level test (`decodemv.c:892`,
    /// `read_intra_frame_mode_info`): on an intra frame whose header set
    /// `allow_intrabc`, EVERY intra block reads a `use_intrabc` symbol right
    /// after `skip`/`cdef`/`delta_q` and before `mbmi->mode`. There is no
    /// block-shape term, so rect strips read it exactly like square leaves --
    /// `read_intra_mode_rect` never did, and the arithmetic decoder desynced
    /// at the FIRST symbol of the first rect block of every
    /// `--tune-content=screen` key frame (measured: `testsrc2` 256x192 cq59
    /// 8-bit decoded "OK" with all 49152 luma samples wrong).
    ///
    /// Arm 0 is that recipe at cq50 without palette: its rect strips really do
    /// use intrabc, which this decoder cannot reconstruct, so it must stop on
    /// the NAMED refusal instead of emitting a wrong frame -- and it must have
    /// read the symbol to get there.
    /// Arm 1 is the same recipe without palette and without tx-size search --
    /// it decodes the whole frame, reading the symbol dozens of times.
    /// Arm 2 is a screen-tools key frame whose header does NOT set
    /// `allow_intrabc` (cq63): it stays pixel-exact, proving the new read is
    /// not taken when libaom does not write it.
    ///
    /// PIXEL RESIDUE (open, lane-kf900 r5): arm 1's frame is entropy-exact
    /// against the instrumented aomdec for 429 mode-ladder elements and then
    /// diverges inside the DV read of a SQUARE intrabc block at mi(32,44), so
    /// its pixels are not compared here. That is a separate defect in
    /// `read_intrabc_dv`, not in the read this gate covers.
    #[test]
    fn a_real_aomenc_screen_key_frame_reads_use_intrabc_on_rect_strips() {
        const NAME: &str = "a_real_aomenc_screen_key_frame_reads_use_intrabc_on_rect_strips";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let (width, height) = (256usize, 192usize);
        // (arm, source, per-arm overrides AFTER the base recipe, expect_refusal,
        //  must_read_use_intrabc)
        const TS: &str = "testsrc2=s=256x192:r=25";
        const SB: &str = "smptebars=size=256x192:rate=25";
        // (arm, source, per-arm overrides AFTER the base recipe, expect_refusal,
        //  must_read_use_intrabc_on_a_rect_strip)
        let arms: [(&str, &str, &[&str], bool, bool); 8] = [
            ("testsrc2-cq50-txs0", TS, &["--cq-level=50", "--enable-palette=0", "--enable-tx-size-search=0"], true, true),
            ("smptebars-cq40-txs0", SB, &["--cq-level=40", "--enable-palette=0", "--enable-tx-size-search=0"], false, false),
            ("smptebars-cq45-txs0", SB, &["--cq-level=45", "--enable-palette=0", "--enable-tx-size-search=0"], false, true),
            ("smptebars-cq45-txs1", SB, &["--cq-level=45", "--enable-palette=0", "--enable-tx-size-search=1"], false, false),
            ("smptebars-cq50-txs1", SB, &["--cq-level=50", "--enable-palette=0", "--enable-tx-size-search=1"], false, false),
            ("smptebars-cq55-txs0", SB, &["--cq-level=55", "--enable-palette=0", "--enable-tx-size-search=0"], false, false),
            ("testsrc2-cq63-txs1", TS, &["--cq-level=63", "--enable-palette=0", "--enable-tx-size-search=1"], false, false),
            // lane-kf900 r7: the 8x8-LEAF intrabc arm. Rect and 1:4
            // partitions off (so no rect strip refuses first), palette on,
            // `TxMode::Largest`: aomenc puts exactly one `use_intrabc` block
            // on a `BLOCK_8X8` leaf here, the shape `decode_leaf8` decoded as
            // ordinary intra before this round.
            ("testsrc2-cq55-leaf8", TS, &["--cq-level=55", "--enable-palette=1", "--enable-tx-size-search=0", "--enable-rect-partitions=0", "--enable-1to4-partitions=0"], false, false),
        ];
        let (mut reads_total, mut refused, mut frames_compared) = (0usize, 0u32, 0usize);
        let (mut blocks_total, mut fired_arms, mut out_of_scope, mut out_of_scope_mismatch) =
            (0usize, 0u32, 0u32, 0u32);
        let mut leaf8_total = 0usize;
        for (arm, src, extra, expect_refusal, must_read) in &arms {
            let render = || {
                let out = Command::new("ffmpeg")
                    .args([
                        "-v", "error", "-f", "lavfi", "-i", *src, "-t", "0.2", "-pix_fmt",
                        "yuv420p", "-strict", "-1", "-f", "yuv4mpegpipe", "-",
                    ])
                    .stdin(Stdio::null())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .output()
                    .expect("ffmpeg failed to run");
                assert!(out.status.success(), "{NAME}: ffmpeg failed for {arm}");
                out.stdout
            };
            let y4m_a = render();
            let y4m_b = render();
            assert_eq!(y4m_a, y4m_b, "{NAME}: {arm} must render byte-identical across two runs");
            let y4m = y4m_a;
            let mut child = Command::new(aomenc_path())
                .args([
                    "--codec=av1",
                    "--bit-depth=8",
                    "--input-bit-depth=8",
                    "--passes=1",
                    "--end-usage=q",
                    "--cpu-used=0",
                    "--lag-in-frames=0",
                    "--kf-max-dist=1",
                    "--limit=1",
                    "--threads=1",
                    "--tile-columns=0",
                    "--enable-rect-partitions=1",
                    "--enable-1to4-partitions=1",
                    "--min-partition-size=8",
                    "--max-partition-size=32",
                    "--sb-size=64",
                    // `allow_screen_content_tools` (and with it the frame
                    // header's `allow_intrabc` bit) comes from here.
                    "--tune-content=screen",
                    // Spelled so `gate_coverage` counts the tool as exercised
                    // rather than defaulted (class `tool-disabled-in-every-gate`).
                    "--enable-intrabc=1",
                ])
                // aomenc keeps the LAST occurrence of a repeated flag.
                .args(*extra)
                .args(["--obu", "-o", "-", "-"])
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .expect("aomenc failed to start");
            child
                .stdin
                .take()
                .expect("aomenc stdin")
                .write_all(&y4m)
                .or_else(|e| match e.kind() {
                    std::io::ErrorKind::BrokenPipe => Ok(()),
                    _ => Err(e),
                })
                .expect("writing y4m to aomenc");
            let out = child.wait_with_output().expect("aomenc failed to run");
            assert!(
                out.status.success(),
                "{NAME}: aomenc refused {arm}: {}",
                String::from_utf8_lossy(&out.stderr)
            );
            let stream = out.stdout;
            decode::reset_rect_intrabc_reads();
            crate::decode::reset_intrabc_hits();
            crate::decode::reset_leaf8_intrabc_hits();
            let decoded = decode_stream(&stream);
            let reads = decode::rect_intrabc_reads();
            // Blocks that decoded `use_intrabc == 1` (square path), i.e. that
            // read a DV and predicted from the current frame -- distinct from
            // `reads`, which counts rect strips that merely READ the flag.
            let blocks = crate::decode::intrabc_hits();
            reads_total += reads;
            blocks_total += blocks;
            // The 8x8-leaf shape has its own counter: without it this gate's
            // other arms (all rect/32x32 intrabc) would stay green while the
            // leaf path decoded an intrabc block as ordinary intra (class
            // `gate-blind-to-feature`).
            let leaf8 = crate::decode::leaf8_intrabc_hits();
            leaf8_total += leaf8;
            if *arm == "testsrc2-cq55-leaf8" {
                assert!(
                    leaf8 > 0,
                    "{NAME}: {arm} decoded no intrabc block at an 8x8 leaf -- the arm no                      longer exercises `decode_leaf8`'s intrabc path"
                );
            }
            if *must_read {
                assert!(
                    reads > 0,
                    "{NAME}: {arm} read no use_intrabc symbol on a rect strip -- the \
                     arm no longer exercises the fix (allow_intrabc not set?)"
                );
            }
            match decoded {
                Ok(frames) => {
                    assert!(
                        !*expect_refusal,
                        "{NAME}: {arm} decoded a frame whose rect strips use intrabc -- \
                         reconstruction is not ported, it must refuse by name"
                    );
                    assert!(!frames.is_empty(), "{NAME}: {arm} decoded no frame");
                    let ffmpeg_frames = ffmpeg_decode_sequence(&stream, width, height, frames.len());
                    assert_eq!(frames.len(), ffmpeg_frames.len(), "{NAME}: {arm} frame count");
                    // EVERY frame is compared; an arm whose decode never hit an
                    // intrabc block proves nothing about the DV/prediction path,
                    // so it is counted OUT OF SCOPE -- but a mismatch there is
                    // still a failure (`out_of_scope_mismatch == 0`), never a skip.
                    let mut same = true;
                    for (i, (ours, theirs)) in frames.iter().zip(ffmpeg_frames.iter()).enumerate() {
                        let ok = ours.y == theirs.y && ours.u == theirs.u && ours.v == theirs.v;
                        if !ok {
                            eprintln!("{NAME}: {arm} MISMATCH at frame {i}");
                        }
                        same &= ok;
                        frames_compared += 1;
                    }
                    if blocks > 0 {
                        fired_arms += 1;
                        assert!(
                            same,
                            "{NAME}: {arm} decoded {blocks} intrabc block(s) and did not match ffmpeg"
                        );
                    } else {
                        out_of_scope += 1;
                        if !same {
                            out_of_scope_mismatch += 1;
                        }
                    }
                    eprintln!(
                        "{NAME}: {arm} {} frame(s), {reads} rect use_intrabc reads, \
                         {blocks} intrabc block(s), exact={same}",
                        frames.len()
                    );
                }
                Err(e) => {
                    let msg = e.to_string();
                    assert!(msg.contains("unsupported"), "{NAME}: {arm} decode failed: {e}");
                    assert!(
                        *expect_refusal,
                        "{NAME}: {arm} was expected to decode, it refused: {e}"
                    );
                    assert!(
                        msg.contains("intra block copy") || msg.contains("intrabc"),
                        "{NAME}: {arm} refused for an unrelated reason: {e}"
                    );
                    eprintln!("{NAME}: {arm} REFUSED (expected): {e}");
                    refused += 1;
                }
            }
        }
        eprintln!(
            "{NAME}: {reads_total} rect-strip use_intrabc symbol(s) read, \
             {blocks_total} intrabc block(s) decoded across {fired_arms} arm(s), \
             {refused} refused by name, {frames_compared} frames compared, \
             {out_of_scope} out of scope ({out_of_scope_mismatch} mismatched)"
        );
        eprintln!("{NAME}: {leaf8_total} intrabc block(s) at an 8x8 leaf");
        assert!(reads_total > 0, "{NAME}: gate is vacuous -- no arm read the symbol");
        assert!(
            leaf8_total > 0,
            "{NAME}: no arm decoded an intrabc block at an 8x8 leaf -- lane-kf900 r7's fix              is untested"
        );
        assert!(
            blocks_total > 0 && fired_arms > 0,
            "{NAME}: gate is vacuous -- no compared arm actually decoded an intrabc block"
        );
        assert_eq!(refused, 1, "{NAME}: expected exactly one named intrabc refusal");
        assert!(frames_compared > 0, "{NAME}: no frame was compared pixel-exact");
        assert_eq!(
            out_of_scope_mismatch, 0,
            "{NAME}: an arm without an intrabc block still mismatched ffmpeg"
        );
    }

    /// lane-kf900 r4, the gate for the two lifted palette refusals ("a 1:4
    /// rect strip that actually uses a palette (reconstruction is not ported
    /// at this shape)" and "a palette block on a HORZ/VERT intra strip below
    /// 16x16 (reconstruction not ported)"): real `aomenc` streams that put a
    /// palette on a RECT strip, decoded whole-frame pixel-exact against
    /// ffmpeg's own decode of the identical bytes, at 8 AND 10 bit.
    ///
    /// Arm 0 is the stream lane-kf900 r3 pinned and stopped on -- `testsrc2`
    /// 256x192, `--cq-level=59 --cpu-used=0 --min-partition-size=8
    /// --enable-rect-partitions=1 --enable-tx-size-search=1`, md5
    /// `e5f033d8fe34e4418d8cca3ac9d2b595` at 10 bit. Arms 1-2 force the shape
    /// on screen-like content with `--tune-content=screen --enable-palette=1
    /// --enable-1to4-partitions=1`.
    ///
    /// An attempt whose decode never hit a rect-strip palette block proves
    /// nothing about the lift, so it is counted OUT OF SCOPE rather than
    /// silently passing -- but a mismatch on one is still a failure
    /// (`out_of_scope_mismatch == 0`), and at least one attempt must fire the
    /// counter or the gate is vacuous.
    #[test]
    fn a_real_aomenc_rect_strip_palette_decodes_pixel_exact() {
        const NAME: &str = "a_real_aomenc_rect_strip_palette_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let (width, height) = (256usize, 192usize);
        let screen: &[&str] = &[
            "--tune-content=screen",
            "--enable-palette=1",
            "--enable-1to4-partitions=1",
            "--min-partition-size=8",
        ];
        // lane-kf900 r6: arms 3-4 are the palette + `--enable-tx-size-search=1`
        // shape whose neighbour palette lookup was SUB-granular -- a 16x8 strip
        // pair shares one 16px cell, so strip 1 read strip 0's palette size and
        // the colour cache came out short. Both were whole-frame wrong before
        // the mi-granular fix (`$HOME/.cache/kf900-r6/sweep.log`: smptebars
        // cq40/cq55 txs=1 pal=1 = DIFF).
        let screen_txs: &[&str] = &[
            "--tune-content=screen",
            "--enable-palette=1",
            "--enable-1to4-partitions=1",
            "--min-partition-size=8",
            "--max-partition-size=32",
            "--sb-size=64",
            "--enable-intrabc=1",
            "--enable-tx-size-search=1",
        ];
        let cq40: Vec<&str> = screen_txs.iter().copied().chain(["--cq-level=40"]).collect();
        let cq55: Vec<&str> = screen_txs.iter().copied().chain(["--cq-level=55"]).collect();
        let arms: [(&str, String, &[&str]); 5] = [
            ("testsrc2-pinned", "testsrc2=s=256x192:r=25".to_string(), &[]),
            ("testsrc2-screen", "testsrc2=s=256x192:r=25".to_string(), screen),
            ("smptebars-screen", "smptebars=size=256x192:rate=25".to_string(), screen),
            ("smptebars-screen-txs-cq40", "smptebars=size=256x192:rate=25".to_string(), &cq40),
            ("smptebars-screen-txs-cq55", "smptebars=size=256x192:rate=25".to_string(), &cq55),
        ];
        let (mut fired_arms, mut out_of_scope, mut out_of_scope_mismatch) = (0u32, 0u32, 0u32);
        let mut refused = 0u32;
        let mut fired_at_depth = [0u32; 2];
        let mut frames_compared = 0usize;
        for (arm, src, extra) in &arms {
            for depth in [8usize, 10] {
                let pix_fmt = if depth == 10 { "yuv420p10le" } else { "yuv420p" };
                let render = || {
                    let out = Command::new("ffmpeg")
                        .args([
                            "-v", "error", "-f", "lavfi", "-i", src.as_str(), "-t", "0.2",
                            "-pix_fmt", pix_fmt, "-strict", "-1", "-f", "yuv4mpegpipe", "-",
                        ])
                        .stdin(Stdio::null())
                        .stdout(Stdio::piped())
                        .stderr(Stdio::piped())
                        .output()
                        .expect("ffmpeg failed to run");
                    assert!(out.status.success(), "{NAME}: ffmpeg failed for {arm}");
                    out.stdout
                };
                let y4m_a = render();
                let y4m_b = render();
                assert_eq!(
                    y4m_a, y4m_b,
                    "{NAME}: {arm} must render byte-identical across two runs at {depth}-bit"
                );
                let y4m = y4m_a;
                let depth_arg = format!("--bit-depth={depth}");
                let in_depth_arg = format!("--input-bit-depth={depth}");
                let mut child = Command::new(aomenc_path())
                    .args(["--codec=av1"])
                    .args([&depth_arg, &in_depth_arg])
                    .args([
                        "--passes=1",
                        "--end-usage=q",
                        "--cq-level=59",
                        "--cpu-used=0",
                        "--lag-in-frames=0",
                        "--kf-max-dist=1",
                        "--limit=1",
                        "--threads=1",
                        "--tile-columns=0",
                        "--enable-tx-size-search=1",
                        "--min-partition-size=8",
                        "--enable-rect-partitions=1",
                    ])
                    // Per-arm overrides go AFTER the base recipe: aomenc keeps
                    // the LAST occurrence of a repeated flag.
                    .args(*extra)
                    // The 8-bit twin of the pinned recipe picks a 128-root
                    // HORZ partition, which this decoder still refuses by name
                    // ("a 128x128 superblock HORZ/VERT or AB partition") --
                    // an open refusal of another lane, unrelated to palette.
                    // Pinning the superblock to 64 keeps the 8-bit arm on the
                    // shape this gate is about; the 10-bit arms are the
                    // untouched pinned recipe.
                    .args(if depth == 8 { &["--sb-size=64"][..] } else { &[][..] })
                    .args(["--obu", "-o", "-", "-"])
                    .stdin(Stdio::piped())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .spawn()
                    .expect("aomenc failed to start");
                child
                    .stdin
                    .take()
                    .expect("aomenc stdin")
                    .write_all(&y4m)
                    .or_else(|e| match e.kind() {
                        // aomenc rejecting the input closes the pipe before we
                        // finish writing; its own stderr below is the report.
                        std::io::ErrorKind::BrokenPipe => Ok(()),
                        _ => Err(e),
                    })
                    .expect("writing y4m to aomenc");
                let out = child.wait_with_output().expect("aomenc failed to run");
                assert!(
                    out.status.success(),
                    "{NAME}: aomenc refused {arm} at {depth}-bit: {}",
                    String::from_utf8_lossy(&out.stderr)
                );
                let stream = out.stdout;
                let before = decode::rect4_palette_hits();
                let frames = match decode_stream(&stream) {
                    Ok(frames) => frames,
                    // A NAMED refusal is another lane's open shape (here: a
                    // palette on an 8x8 SQUARE leaf, still out of scope), never
                    // a pass -- the attempt is counted out of scope and the
                    // per-depth firing assert below keeps the gate honest.
                    Err(e) if e.to_string().contains("unsupported") => {
                        eprintln!("{NAME}: {arm} {depth}-bit REFUSED: {e}");
                        refused += 1;
                        continue;
                    }
                    Err(e) => panic!("{NAME}: decode failed on {arm} at {depth}-bit: {e}"),
                };
                let fired = decode::rect4_palette_hits() - before;
                let ffmpeg_frames = if depth == 10 {
                    ffmpeg_decode_sequence_10bit(&stream, width, height, frames.len())
                } else {
                    ffmpeg_decode_sequence(&stream, width, height, frames.len())
                };
                assert_eq!(
                    frames.len(),
                    ffmpeg_frames.len(),
                    "{NAME}: {arm} at {depth}-bit -- frame count"
                );
                assert!(!frames.is_empty(), "{NAME}: {arm} at {depth}-bit decoded no frame");
                // EVERY decode-order frame, all three planes.
                let mut exact = true;
                for (i, (ours, theirs)) in frames.iter().zip(ffmpeg_frames.iter()).enumerate() {
                    if ours.y != theirs.y || ours.u != theirs.u || ours.v != theirs.v {
                        exact = false;
                        eprintln!("{NAME}: {arm} {depth}-bit frame {i} differs");
                    }
                    frames_compared += 1;
                }
                if fired > 0 {
                    fired_arms += 1;
                    fired_at_depth[usize::from(depth == 10)] += 1;
                    assert!(
                        exact,
                        "{NAME}: {arm} at {depth}-bit has {fired} rect-strip palette block(s) \
                         and does NOT decode pixel-exact"
                    );
                } else {
                    out_of_scope += 1;
                    if !exact {
                        out_of_scope_mismatch += 1;
                    }
                }
            }
        }
        eprintln!(
            "{NAME}: {fired_arms} attempt(s) with a rect-strip palette block, \
             {out_of_scope} out of scope ({out_of_scope_mismatch} mismatched), \
             {refused} refused, {frames_compared} frames compared, \
             fired 8-bit={} 10-bit={}",
            fired_at_depth[0], fired_at_depth[1]
        );
        // MEASURED 2026-09-02, every 8-bit attempt of these recipes: aomenc
        // puts its palettes on SQUARE blocks at 8 bit and every 8-bit stream
        // that reaches a rect strip with one lands on a palette shape still
        // out of scope (8x8 square leaf, or a 64x32/32x64 superblock strip
        // with a real transform). So the 8-bit arms here prove the DECODE
        // path, not the lift -- `fired_at_depth[0] == 0` is a known, reported
        // coverage gap and not a silent pass: the counter is printed.
        assert!(
            fired_at_depth[1] > 0,
            "{NAME}: no attempt put a palette on a rect strip \
             (8-bit={}, 10-bit={}) -- gate is vacuous",
            fired_at_depth[0],
            fired_at_depth[1]
        );
        assert!(fired_arms > 0, "{NAME}: gate is vacuous");
        assert_eq!(
            out_of_scope_mismatch, 0,
            "{NAME}: {out_of_scope_mismatch} attempt(s) without a rect-strip palette block \
             still mismatched -- an unrelated defect, not a SKIP"
        );
    }

    /// lane-hbd r5: a real `aomenc --bit-depth=10` stream, decoded through
    /// this crate's own 10-bit planes (`Picture` widened to `u16` in an
    /// earlier round) and checked pixel-exact against ffmpeg's own decode of
    /// the identical bytes via [`ffmpeg_decode_sequence_10bit`]. Confirms
    /// (hard-asserts, not just trusts) the sequence header this stream
    /// actually parses to says `bit_depth == 10` before trusting any pixel
    /// match -- a stream that silently fell back to 8-bit would still
    /// "match" trivially.
    #[test]
    fn a_real_aomenc_10bit_stream_decodes_pixel_exact() {
        const NAME: &str = "a_real_aomenc_10bit_stream_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let (width, height) = (64usize, 64usize);
        let y4m = Command::new("ffmpeg")
            .args([
                "-v",
                "error",
                "-f",
                "lavfi",
                "-i",
                &gradients_source(42, width, height, "duration=0.04:rate=25"),
                "-pix_fmt",
                "yuv420p10le",
                "-strict",
                "-1",
                "-t",
                "0.04",
                "-f",
                "yuv4mpegpipe",
                "-",
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .output()
            .expect("ffmpeg failed to run");
        assert!(
            y4m.status.success(),
            "ffmpeg failed to render the 10-bit fixture: {}",
            String::from_utf8_lossy(&y4m.stderr)
        );
        let mut child = Command::new(aomenc_path())
            .args([
                "--codec=av1",
                "--passes=1",
                "--end-usage=q",
                "--cq-level=30",
                "--cpu-used=0",
                "--threads=1",
                "--row-mt=0",
                "--sb-size=64",
                "--input-bit-depth=10",
                "--bit-depth=10",
                "--limit=1",
                "--obu",
                "-o",
                "-",
                "-",
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("aomenc failed to start");
        child
            .stdin
            .take()
            .expect("aomenc stdin")
            .write_all(&y4m.stdout)
            .expect("writing y4m to aomenc");
        let out = child.wait_with_output().expect("aomenc failed to run");
        assert!(
            out.status.success(),
            "aomenc refused the 10-bit fixture: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let stream = out.stdout;
        // Confirm the sequence header this stream actually parses to before
        // trusting any pixel comparison below.
        let mut probe = Av1Parser::new();
        let mut pos = 0usize;
        while pos < stream.len() && probe.sequence_header().is_none() {
            let obu = probe.parse_obu(&stream[pos..]).unwrap();
            pos += obu.total_size;
        }
        let seq = probe
            .sequence_header()
            .expect("stream has a sequence header OBU");
        assert_eq!(
            seq.color_config.bit_depth, 10,
            "{NAME}: aomenc did not actually write a 10-bit sequence header"
        );
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused a real 10-bit stream: {e}"),
        };
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "luma vs ffmpeg (10-bit)");
        assert_eq!(frames[0].u, ffmpeg_frames[0].u, "U vs ffmpeg (10-bit)");
        assert_eq!(frames[0].v, ffmpeg_frames[0].v, "V vs ffmpeg (10-bit)");
    }

    /// The 10-bit *inter* counterpart of the gate above: a real `aomenc`
    /// `yuv420p10le` sequence whose non-key frames are plain forward
    /// single-`LAST_FRAME` P frames (same `--lag-in-frames=0
    /// --auto-alt-ref=0 --error-resilient=1` shape as the 8-bit inter gate),
    /// decoded pixel-exact on every frame. 10-bit intra was proven exact by
    /// lane-hbd; inter reconstruction at `bit_depth == 10` was never gated.
    #[test]
    fn a_real_aomenc_10bit_inter_sequence_decodes_pixel_exact() {
        const NAME: &str = "a_real_aomenc_10bit_inter_sequence_decodes_pixel_exact";
        let _gate_lock = lock_gate_counters();
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let (width, height, frame_count) = (128usize, 64usize, 16usize);
        let y4m = Command::new("ffmpeg")
            .args([
                "-v",
                "error",
                "-f",
                "lavfi",
                "-i",
                &gradients_source(42, width, height, "duration=0.64:rate=25"),
                "-pix_fmt",
                "yuv420p10le",
                "-strict",
                "-1",
                "-t",
                "0.64",
                "-f",
                "yuv4mpegpipe",
                "-",
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .output()
            .expect("ffmpeg failed to run");
        assert!(
            y4m.status.success(),
            "ffmpeg failed to render the 10-bit fixture: {}",
            String::from_utf8_lossy(&y4m.stderr)
        );
        let mut child = Command::new(aomenc_path())
            .args([
                // lane-defon r1: explicit on-value (aomenc keeps the FIRST
                // occurrence, so overrides go before the base list).
                "--loopfilter-control=1",
                "--codec=av1",
                "--passes=1",
                "--end-usage=q",
                "--cq-level=15",
                "--cpu-used=0",
                "--threads=1",
                "--row-mt=0",
                "--sb-size=64",
                "--input-bit-depth=10",
                "--bit-depth=10",
                "--lag-in-frames=0",
                "--auto-alt-ref=0",
                "--kf-max-dist=1000",
                "--error-resilient=1",
                "--aq-mode=0",
                "--deltaq-mode=0",
                "--enable-cdef=0",
                "--enable-rect-partitions=0",
                "--enable-ab-partitions=0",
                "--enable-1to4-partitions=0",
                "--enable-filter-intra=0",
                "--enable-smooth-intra=0",
                "--enable-paeth-intra=0",
                "--enable-directional-intra=0",
                "--enable-angle-delta=0",
                "--enable-tx-size-search=0",
                "--enable-cdef=1",
                "--enable-restoration=1",
                "--min-partition-size=16",
                "--max-partition-size=32",
                "--enable-palette=0",
                "--enable-intrabc=0",
                "--enable-cfl-intra=0",
                "--enable-ref-frame-mvs=0",
                "--obu",
                "-o",
                "-",
                "-",
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("aomenc failed to start");
        child
            .stdin
            .take()
            .expect("aomenc stdin")
            .write_all(&y4m.stdout)
            .expect("writing y4m to aomenc");
        let out = child.wait_with_output().expect("aomenc failed to run");
        assert!(
            out.status.success(),
            "aomenc refused the 10-bit fixture: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let stream = out.stdout;
        if let Ok(dump) = std::env::var("EC_AV1_GATE_DUMP") {
            std::fs::write(dump, &stream).expect("dump stream");
        }
        let mut probe = Av1Parser::new();
        let mut pos = 0usize;
        while pos < stream.len() && probe.sequence_header().is_none() {
            let obu = probe.parse_obu(&stream[pos..]).unwrap();
            pos += obu.total_size;
        }
        assert_eq!(
            probe
                .sequence_header()
                .expect("stream has a sequence header OBU")
                .color_config
                .bit_depth,
            10,
            "{NAME}: aomenc did not actually write a 10-bit sequence header"
        );
        let before_deblock = decode::deblock_hits();
        let before_inter = decode::inter_pred_hits();
        let before_lr = crate::restoration::wiener_hits()
            + crate::restoration::sgrproj_hits()
            + crate::restoration::switchable_hits();
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused a real 10-bit inter stream: {e}"),
        };
        assert!(
            decode::inter_pred_hits() > before_inter,
            "{NAME}: no inter-predicted block decoded -- the gate proves nothing"
        );
        assert!(
            decode::deblock_hits() > before_deblock,
            "{NAME}: no deblocking edge fired -- raise cq-level"
        );
        // Loop restoration is where the 10-bit inter/intra defect lived
        // (lane-hbdinter r1: the self-guided box sums were never brought back
        // to the 8-bit scale, `restoration.c:660`); a recipe whose RD happened
        // to pick RESTORE_NONE would pass while proving nothing.
        assert!(
            crate::restoration::wiener_hits()
                + crate::restoration::sgrproj_hits()
                + crate::restoration::switchable_hits()
                > before_lr,
            "{NAME}: no loop-restoration unit decoded a real filter -- lower cq-level"
        );
        eprintln!(
            "{NAME}: inter_pred {} deblock {} cdef_idx {} wiener {} sgrproj {}",
            decode::inter_pred_hits() - before_inter,
            decode::deblock_hits() - before_deblock,
            decode::cdef_idx_hits(),
            crate::restoration::wiener_hits(),
            crate::restoration::sgrproj_hits(),
        );
        assert_eq!(frames.len(), frame_count);
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, frame_count);
        for (i, (got, want)) in frames.iter().zip(&ffmpeg_frames).enumerate() {
            if got.y != want.y || got.u != want.u || got.v != want.v {
                let pin = std::env::temp_dir().join("ec-av1-10bit-inter-gate-fail.obu");
                let _ = std::fs::write(&pin, &stream);
                let first = |a: &Vec<u16>, b: &Vec<u16>| {
                    a.iter()
                        .zip(b)
                        .enumerate()
                        .find(|(_, (x, y))| x != y)
                        .map(|(k, (x, y))| (k, *x, *y))
                };
                panic!(
                    "{NAME}: frame {i} mismatch vs ffmpeg -- Y {:?} U {:?} V {:?}; stream pinned at {}",
                    first(&got.y, &want.y),
                    first(&got.u, &want.u),
                    first(&got.v, &want.v),
                    pin.display()
                );
            }
        }
    }

    /// lane-hbd10 r1: a real `aomenc --bit-depth=10 --film-grain-test=1`
    /// stream, decoded pixel-exact against ffmpeg's own 10-bit decode of the
    /// identical bytes (ffmpeg synthesizes grain by default -- no
    /// grain-disable flag is passed anywhere in this file). Proves the
    /// bit-depth-generic grain path (`film_grain.rs`'s `grain_range`,
    /// `scale_lut`, the `<< (bit_depth - 8)` offsets/legal ranges) rather
    /// than the old `bit_depth != 8` refusal. HARD-asserts both the parsed
    /// `bit_depth == 10` and `film_grain::grain_hits() > 0`, so neither a
    /// silent 8-bit fallback nor a stream aomenc emitted without
    /// `apply_grain` can make it pass vacuously.
    #[test]
    fn a_real_aomenc_10bit_film_grain_stream_decodes_pixel_exact() {
        const NAME: &str = "a_real_aomenc_10bit_film_grain_stream_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        if !have_aomenc() {
            eprintln!("SKIP {NAME}: no aomenc at {}", aomenc_path().display());
            return;
        }
        let (width, height) = (64usize, 64usize);
        let stream = encode_10bit_gradients(
            NAME,
            width,
            height,
            1,
            &["--film-grain-test=1", "--limit=1"],
        );
        assert_eq!(
            parsed_bit_depth(&stream),
            10,
            "{NAME}: aomenc did not actually write a 10-bit sequence header"
        );
        let mut probe = Av1Parser::new();
        let mut pos = 0usize;
        let mut saw_grain = false;
        while pos < stream.len() {
            let obu = probe.parse_obu(&stream[pos..]).unwrap();
            pos += obu.total_size;
            if let ObuKind::Frame(header, _) = obu.kind
                && header.film_grain.apply_grain
            {
                // A grain block whose scaling LUT is empty would blend a
                // zero delta into every pixel and let this gate pass without
                // the bit-depth math mattering at all.
                assert!(
                    header.film_grain.num_y_points > 0,
                    "{NAME}: apply_grain with no luma scaling points -- grain would be a no-op"
                );
                saw_grain = true;
            }
        }
        assert!(saw_grain, "{NAME}: aomenc did not turn on apply_grain");
        let before = crate::film_grain::grain_hits();
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused: {e}"),
        };
        assert!(
            crate::film_grain::grain_hits() > before,
            "{NAME}: matched but zero grain_hits -- grain synthesis never ran"
        );
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "{NAME}: luma vs ffmpeg");
        assert_eq!(frames[0].u, ffmpeg_frames[0].u, "{NAME}: U vs ffmpeg");
        assert_eq!(frames[0].v, ffmpeg_frames[0].v, "{NAME}: V vs ffmpeg");
        eprintln!("{NAME}: pixel-exact, grain_hits={}", crate::film_grain::grain_hits());
    }

    /// lane-golomb r1: THE FILM ITSELF. `crates/ec-av1/fixtures/hg_head_key_frame.obu`
    /// is the first frame of the user's Hunger Games AV1 release (3840x1608
    /// yuv420p10le, `ffmpeg -i <mkv> -c copy -frames:v 1 -f obu`, 147 bytes) --
    /// a real 10-bit key frame whose height is NOT a multiple of the 64-pixel
    /// superblock, so its last superblock row (mi_row=400 of 402) carries the
    /// edge partition symbol this lane fixed: libaom's `ec_read_partition_impl`
    /// returns `PARTITION_HORZ` when the gathered `split_or_horz` bit is 0, and
    /// this decoder used to READ that bit and throw it away, forcing SPLIT
    /// (class `parsed-then-discarded`). The desync surfaced two rows later as
    /// "a Golomb tail longer than this decoder reads" -- a refusal naming the
    /// symptom, never the cause.
    #[test]
    fn the_hunger_games_head_key_frame_decodes_pixel_exact() {
        const NAME: &str = "the_hunger_games_head_key_frame_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("fixtures/hg_head_key_frame.obu");
        let stream = std::fs::read(&path)
            .unwrap_or_else(|e| panic!("{NAME}: reading {}: {e}", path.display()));
        let (width, height) = (3840usize, 1608usize);
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused: {e}"),
        };
        assert_eq!(frames.len(), 1, "{NAME}: one key frame");
        assert_eq!((frames[0].width, frames[0].height), (width, height));
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "{NAME}: luma vs ffmpeg");
        assert_eq!(frames[0].u, ffmpeg_frames[0].u, "{NAME}: U vs ffmpeg");
        assert_eq!(frames[0].v, ffmpeg_frames[0].v, "{NAME}: V vs ffmpeg");
    }
    /// lane-troykf r2: `crates/ec-av1/fixtures/troy_kf2700.obu` is a 1920x792
    /// 10-bit AV1 key frame taken out of one of the user's own films
    /// (`ffmpeg -ss 2700 -c:v copy -f obu`, then truncated to its first temporal
    /// unit, 36 kB) -- the ONLY stream in this repo that contains a SKIPPED
    /// `UV_CFL_PRED` block. 30 aomenc recipes (r1's 20 plus r2's chroma-correlated
    /// `geq` sweep, cq 40..63, cpu-used 0..2, min/max-partition 4..64, 8 and
    /// 10 bit) never made the encoder pick one, so the counter can only be
    /// hard-asserted against a real film frame. The instrumented oracle agrees:
    /// `EC_TRACE_MODE=1 aomdec` prints 5 `EC_IMODE_VAL ... uv_mode=13 skip=1`
    /// lines for this frame.
    ///
    /// The defect it pins (fixed at 29cd53f, `decode.rs:7719`/`:10528`/`:10891`):
    /// a skipped intra block must still PREDICT with CfL -- libaom's
    /// `predict_and_reconstruct_intra_block` predicts every plane and guards only
    /// the residual on `skip_txfm`. Before the fix this frame had 499 wrong
    /// chroma samples (U rows 48..79 cols 464..492); after it, zero.
    ///
    /// The ffmpeg reference is `ffmpeg -f obu -i <fixture> -f rawvideo
    /// -pix_fmt yuv420p10le -` (what `ffmpeg_decode_sequence_10bit` runs).
    #[test]
    fn a_real_film_key_frame_with_a_skipped_cfl_block_decodes_pixel_exact() {
        const NAME: &str = "a_real_film_key_frame_with_a_skipped_cfl_block_decodes_pixel_exact";
        let path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/troy_kf2700.obu");
        let stream = std::fs::read(&path)
            .unwrap_or_else(|e| panic!("{NAME}: reading {}: {e}", path.display()));
        let (width, height) = (1920usize, 792usize);
        let before = crate::decode::troy_chroma_counters();
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused: {e}"),
        };
        let after = crate::decode::troy_chroma_counters();
        let skip_cfl = after.0 - before.0;
        assert_eq!(frames.len(), 1, "{NAME}: one key frame");
        assert_eq!((frames[0].width, frames[0].height), (width, height));
        // Asserted before the ffmpeg compare so an absent ffmpeg cannot make the
        // gate vacuous: the skipped-CfL path is exercised on every run.
        assert!(
            skip_cfl > 0,
            "{NAME}: zero skipped-CfL blocks -- the fixture no longer exercises defect 1"
        );
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME} pixel compare: no ffmpeg (skipped_cfl={skip_cfl})");
            return;
        }
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "{NAME}: luma vs ffmpeg");
        assert_eq!(
            frames[0].u, ffmpeg_frames[0].u,
            "{NAME}: U vs ffmpeg ({skip_cfl} skipped-CfL blocks)"
        );
        assert_eq!(
            frames[0].v, ffmpeg_frames[0].v,
            "{NAME}: V vs ffmpeg ({skip_cfl} skipped-CfL blocks)"
        );
        eprintln!("{NAME}: pixel-exact, skipped_cfl={skip_cfl}");
    }

    /// lane-kf1200 r2: the same film's `-ss 300` key frame, pinned because no
    /// aomenc recipe reaches its shape -- a SKIPPED sub-8x8 chroma block whose
    /// `uv_mode` is `UV_CFL_PRED`. (lane-troykf r1 burned 20 recipes across cq
    /// 40..63 and nine lavfi sources hunting exactly this block and never got
    /// one; ledger dead-end "never produced a SKIPPED 1:4 or sub-8x8 CfL
    /// block".) Before the fix the two sub-8x8 skip arms passed `None` for the
    /// CfL argument, so the block reconstructed as flat DC and 463 bytes of
    /// this frame's chroma were wrong. HARD-asserts `skip_cfl_hits` moved, so
    /// the fixture cannot silently stop exercising the arm.
    #[test]
    fn the_hunger_games_ss300_key_frame_skipped_cfl_decodes_pixel_exact() {
        const NAME: &str = "the_hunger_games_ss300_key_frame_skipped_cfl_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("fixtures/hg_ss300_key_frame.obu");
        let stream = std::fs::read(&path)
            .unwrap_or_else(|e| panic!("{NAME}: reading {}: {e}", path.display()));
        let (width, height) = (3840usize, 1608usize);
        let before = crate::decode::skip_cfl_hits();
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused: {e}"),
        };
        let skipped_cfl = crate::decode::skip_cfl_hits() - before;
        assert!(
            skipped_cfl > 0,
            "{NAME}: zero skipped sub-8x8 CfL blocks -- the fixture no longer \
             exercises the arm this test exists for"
        );
        assert_eq!(frames.len(), 1, "{NAME}: one key frame");
        assert_eq!((frames[0].width, frames[0].height), (width, height));
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "{NAME}: luma vs ffmpeg");
        assert_eq!(frames[0].u, ffmpeg_frames[0].u, "{NAME}: U vs ffmpeg");
        assert_eq!(frames[0].v, ffmpeg_frames[0].v, "{NAME}: V vs ffmpeg");
        eprintln!("{NAME}: {skipped_cfl} skipped sub-8x8 CfL chroma blocks, frame pixel-exact");
    }

    /// lane-kf900 r2: the film's key frame at -ss 900, one frame
    /// (`crates/ec-av1/fixtures/hg_kf900.obu`, 484640 bytes, sha256
    /// `a273ae99328388be14a1ff8fa1c5a6d391a9948159eaef120e1b50e02015eb83`,
    /// extracted twice from independent
    /// `ffmpeg -ss 900 -t 2 -i <2160p AV1 HDR10 mkv> -c:v copy -f obu` runs and
    /// truncated to the first frame; both extracts hashed identically).
    ///
    /// This is the ONLY stream that reaches the r1 defect: a SKIPPED 8x8 intra
    /// leaf whose `tx_depth` symbol resolved to `TX_4X4` still publishes 4 --
    /// not its 8-pixel block side -- to the next block's `get_tx_size_context`
    /// (`set_txfm_ctxs(mbmi->tx_size, bw, bh, skip_txfm && is_inter_block(...))`,
    /// `decodemv.c`; the skip term is 0 for intra). It fires 15 times here and
    /// zero times across 108 measured aomenc recipes, so the counter is
    /// asserted against the film rather than against a synthesised stream.
    ///
    /// LUMA only. U/V still differ (open residue, lane-kf900 r2: 221 U and
    /// 47912 V samples, max |d| 23/2, first at chroma (195, 640) -- chroma
    /// RESIDUAL, the prediction there is bit-exact against aomdec's
    /// `EC_PREDOUT`), so this gate pins what is proven and no more.
    #[test]
    fn a_10bit_key_frame_with_skipped_8x8_intra_leaves_that_split_their_transform_decodes_luma_exact()
    {
        const NAME: &str = "a_10bit_key_frame_with_skipped_8x8_intra_leaves_that_split_their_transform_decodes_luma_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/hg_kf900.obu");
        let stream = std::fs::read(&path)
            .unwrap_or_else(|e| panic!("{NAME}: reading {}: {e}", path.display()));
        let (width, height) = (3840usize, 1608usize);
        crate::decode::reset_skip_split_tx_hits();
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused: {e}"),
        };
        assert_eq!(frames.len(), 1, "{NAME}: one key frame");
        assert_eq!((frames[0].width, frames[0].height), (width, height));
        assert!(
            crate::decode::skip_split_tx_hits() >= 15,
            "{NAME}: skip_split_tx_hits() == {} -- the stream that carries the tx-context \
             defect stopped carrying it, so this gate proves nothing",
            crate::decode::skip_split_tx_hits()
        );
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "{NAME}: luma vs ffmpeg");
    }

    /// lane-kf1200 r3: the same film's `-ss 600` key frame (3840x1608, one
    /// 8-px partial bottom superblock row), pinned because no aomenc recipe
    /// reaches its shape -- a SKIPPED 8x8 intra leaf whose `tx_depth` resolved
    /// to TX_4X4. (80 recipes swept this round: 4 frame shapes x 2 sources x
    /// cq 32..63 x cpu-used 0/3 x 8/10-bit, all with
    /// `--enable-tx-size-search=1 --enable-filter-intra=1`; every one came
    /// back with `skip_split_tx_hits == 0`, `lanes/kf1200-r3.report.md`.)
    /// An intra block reads `tx_depth` whether or not it is skipped, so the
    /// leaf must record its resolved 4 -- not its 8x8 side -- in the txfm
    /// context; recording 8 gave the NEXT block's `tx_depth` symbol the wrong
    /// `tx_size_cdf` row (ctx 2 where libaom reads 1) and desynced the
    /// entropy stream at mi (400,46). HARD-asserts `skip_split_tx_hits` moved.
    #[test]
    fn the_hunger_games_ss600_key_frame_skipped_split_tx_decodes_pixel_exact() {
        const NAME: &str = "the_hunger_games_ss600_key_frame_skipped_split_tx_decodes_pixel_exact";
        if !have_ffmpeg() {
            eprintln!("SKIP {NAME}: no ffmpeg");
            return;
        }
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("fixtures/hg_ss600_key_frame.obu");
        let stream = std::fs::read(&path)
            .unwrap_or_else(|e| panic!("{NAME}: reading {}: {e}", path.display()));
        let (width, height) = (3840usize, 1608usize);
        crate::decode::reset_skip_split_tx_hits();
        let frames = match decode_stream(&stream) {
            Ok(frames) => frames,
            Err(e) => panic!("{NAME}: decode_stream refused: {e}"),
        };
        let skipped_split_tx = crate::decode::skip_split_tx_hits();
        assert!(
            skipped_split_tx > 0,
            "{NAME}: zero skipped 8x8 leaves with a split transform -- the fixture no longer \
             exercises the arm this test exists for"
        );
        assert_eq!(frames.len(), 1, "{NAME}: one key frame");
        assert_eq!((frames[0].width, frames[0].height), (width, height));
        let ffmpeg_frames = ffmpeg_decode_sequence_10bit(&stream, width, height, 1);
        assert_eq!(frames[0].y, ffmpeg_frames[0].y, "{NAME}: luma vs ffmpeg");
        assert_eq!(frames[0].u, ffmpeg_frames[0].u, "{NAME}: U vs ffmpeg");
        assert_eq!(frames[0].v, ffmpeg_frames[0].v, "{NAME}: V vs ffmpeg");
        eprintln!("{NAME}: {skipped_split_tx} skipped 8x8 TX_4X4 leaves, frame pixel-exact");
    }

    /// lane-hbd10 r1: a real `aomenc --bit-depth=10 --superres-mode=1
